for filename, pairs in R.items():
    p = Path(filename)
    text = p.read_text()
    for old, new in pairs:
        count = text.count(old)
        if count != 1:
            raise SystemExit(f'{filename}: expected one match, found {count}: {old[:100]!r}')
        text = text.replace(old, new, 1)
    p.write_text(text)
print(f'Updated {len(R)} pages.')
